<script setup lang="ts">const data=ref<any>(null);const error=ref('');onMounted(async()=>{try{data.value=await $fetch('/api/premium/analytics')}catch{error.value='Аналитика доступна при активном Premium Pro или Elite'}});const points=computed(()=>{const rows=data.value?.balanceSeries||[];if(rows.length<2)return'';const values=rows.map((r:any)=>r.balance),min=Math.min(...values),max=Math.max(...values),range=Math.max(1,max-min);return rows.map((r:any,i:number)=>`${i*600/(rows.length-1)},${190-(r.balance-min)*170/range}`).join(' ')});useHead({title:'Premium аналитика · Poker Dealer Desk'})</script>
<template><main class="page-shell analytics"><NuxtLink to="/premium">← Premium</NuxtLink><header><p>PREMIUM ANALYTICS</p><h1>Ваша игровая динамика</h1></header><p v-if="error" class="panel error">{{ error }}</p><template v-if="data"><section class="panel chart"><div><small>ТЕКУЩИЙ БАЛАНС</small><strong>{{ data.balance.toLocaleString('ru-RU') }}</strong></div><svg viewBox="0 0 600 210" preserveAspectRatio="none" aria-label="График изменения баланса"><polyline :points="points"/></svg><p v-if="!points">Недостаточно данных для графика.</p></section><section class="stats"><article class="panel"><h2>Покер</h2><b>{{ data.poker.hands }}</b><span>раздач · {{ data.poker.winRate }}% побед</span><small>Рейтинг {{ data.poker.tableRating }} · лучшая серия {{ data.poker.bestStreak }}</small></article><article class="panel"><h2>Ракетка</h2><b>{{ data.miniGames.rocket.games }}</b><span>игр</span><small>Ставки {{ data.miniGames.rocket.stake.toLocaleString('ru-RU') }} · выплаты {{ data.miniGames.rocket.payout.toLocaleString('ru-RU') }}</small></article><article class="panel"><h2>Мины</h2><b>{{ data.miniGames.mines.games }}</b><span>игр</span><small>Ставки {{ data.miniGames.mines.stake.toLocaleString('ru-RU') }} · выплаты {{ data.miniGames.mines.payout.toLocaleString('ru-RU') }}</small></article></section></template></main></template>
<style scoped>.analytics{display:grid;gap:1rem;padding-top:1.2rem}.analytics>a{color:var(--accent);text-decoration:none}.analytics header p{color:var(--accent);font-size:.68rem;letter-spacing:.16em}.analytics h1{font-size:clamp(2rem,6vw,4rem);margin:.3rem 0}.chart{min-height:300px}.chart>div{display:flex;justify-content:space-between;align-items:end}.chart strong{font-size:2rem;color:var(--accent)}.chart svg{width:100%;height:210px;margin-top:1rem}.chart polyline{fill:none;stroke:#8fe0b5;stroke-width:4;vector-effect:non-scaling-stroke;filter:drop-shadow(0 0 8px #78d9a866)}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:.8rem}.stats article{display:grid;gap:.35rem}.stats h2{margin:0}.stats b{color:var(--accent);font-size:2rem}.stats span,.stats small{color:var(--text-muted)}.error{color:#ff9b8d}@media(max-width:700px){.stats{grid-template-columns:1fr}.chart{min-height:250px}}</style>
